async(page)=>{
const click=n=>page.locator(`[data-label="${n}"]`).first().click();await page.goto('http://127.0.0.1:18762/final-preview-v4/05_add_assignment.html');
await page.locator('[data-label=assignment_title] input').fill('Psychology seminar');await click('app_review');if(!await page.getByText('Add the key requirements first.').count())throw Error('Textarea empty validation failed');
const field=page.locator('[data-label=assignment_brief] textarea');await field.fill('Compare two studies.\nDiscuss the implications for students.');await page.screenshot({path:'Coursework/prototype/tether-final-build/qa-app/14-multiline-assignment.png'});await click('app_review');await page.waitForURL('**/06_check_requirements.html*');const review=page.locator('[data-label=review_requirements] textarea');if(!(await review.inputValue()).includes('\n'))throw Error('Newline not carried');await review.fill('Compare three studies.\nExplain two implications.');await click('app_edit');await page.waitForURL('**/05_add_assignment.html*');if(await field.inputValue()!=='Compare three studies.\nExplain two implications.')throw Error('Review edits lost');return {ok:true,multiline:true,emptyValidation:true,reviewEditsReturn:true};
}
